const now = new Date();
const runDateDisplay = new Intl.DateTimeFormat("fr-FR", {
  dateStyle: "full",
  timeStyle: "short",
  timeZone: "Europe/Paris",
}).format(now);

return [
  {
    json: {
      workflowName: "repo-ops - maintenance quotidienne",
      runDateIso: now.toISOString(),
      runDateDisplay,
      triggerCommand: "sh -lc \"mkdir -p /files/runtime /files/reports && rm -f /files/reports/worker-summary.json /files/reports/worker-summary.txt /files/reports/worker-summary.html && date -u +%Y-%m-%dT%H:%M:%SZ > /files/runtime/daily-maintenance.trigger\"",
      readReportCommand: "sh -lc \"for i in $(seq 1 30); do if [ -s /files/reports/worker-summary.json ]; then cat /files/reports/worker-summary.json; exit 0; fi; sleep 2; done; echo 'Rapport du worker indisponible.' >&2; exit 1\"",
      mailFrom: "__CONFIGURER_FROM_DANS_N8N__",
      mailTo: "__CONFIGURER_TO_DANS_N8N__",
      workflowNotes: [
        "Le workflow déclenche le worker .NET via un fichier partagé.",
        "Le rapport précédent est supprimé avant chaque trigger pour éviter la lecture d'une sortie obsolète.",
        "Remplacer les marqueurs __CONFIGURER_*__ et associer un credential SMTP avant activation."
      ],
      workflowLogs: [
        "[workflow] Contexte d'exécution préparé.",
        "[workflow] Le worker est déclenché via un fichier partagé dans /files/runtime.",
        "[workflow] n8n attend ensuite un rapport JSON frais produit par le worker."
      ]
    }
  }
];

const data = $input.first().json;
const stdout = data.stdout ?? "{}";
let report;

try {
  report = JSON.parse(stdout);
} catch (error) {
  throw new Error(`Impossible d'analyser la sortie JSON du worker : ${error.message}`);
}

return [
  {
    json: {
      report,
      reportExitCode: data.exitCode ?? 0,
      reportStdout: data.stdout ?? "",
      reportStderr: data.stderr ?? ""
    }
  }
];

const data = $input.first().json;
const report = data.report ?? {};
const digest = report.digest ?? {};

return [
  {
    json: {
      ...data,
      emailSubject: digest.subject ?? `[repo-ops] Synthèse maintenance du ${data.runDateDisplay}`,
      emailText: digest.plainTextBody ?? "Synthèse indisponible.",
      emailHtml: digest.htmlBody ?? "<html lang=\"fr\"><body><p>Synthèse indisponible.</p></body></html>"
    }
  }
];
